def normalize_name(s):
    """Normalize vendor name for comparison"""
    s = s.lower().strip()
    for old, new in [('limited', 'ltd'), ('corporation', 'corp'), ('incorporated', 'inc')]:
        s = s.replace(old, new)
    return s

def fuzzy_ratio(s1, s2):
    """Get similarity ratio between two strings"""
    return SequenceMatcher(None, normalize_name(s1), normalize_name(s2)).ratio()

def find_matching_vendor(invoice_vendor, vendors, threshold=0.85):
    """Find the best matching vendor - prioritize exact match, then best fuzzy match"""
    invoice_norm = normalize_name(invoice_vendor)

    # First, try exact match (after normalization)
    for vendor_name in vendors:
